contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _value) public payable {
        require(address(this).balance >= 0);
        // give C some Ether to work with
        uint amount = 1 ether;
        require(address(this).balance >= amount);
        c.depositsCount(); // read-only touch, ensure fresh state visible
        address(c).call{value: amount}("");
        require(address(c).balance == amount);

        uint balCBefore = address(c).balance;
        uint balTestBefore = address(this).balance;

        bool reverted;
        if (_value > balCBefore) {
            try c.withdraw(_value) { reverted = false; } catch { reverted = true; }
            assert(reverted && address(c).balance == balCBefore);
        } else {
            c.withdraw(_value);
            assert(address(c).balance + _value == balCBefore && address(this).balance == balTestBefore + _value);
        }
    }
    receive() external payable {}
}

